-- Ansaro cinematic v2: blocky part-rigs, full control
local Players=game:GetService("Players")
local RS=game:GetService("RunService")
local AS=game:GetService("AssetService")
local SG=game:GetService("StarterGui")
pcall(function() SG:SetCoreGuiEnabled(Enum.CoreGuiType.All,false) end)
pcall(function() SG:SetCore("TopbarEnabled",false) end)
local cam=workspace.CurrentCamera
local sc=game.ReplicatedStorage:WaitForChild("Scene") task.wait(1)
local bouquet=sc.Bouquet:Clone() bouquet.Parent=workspace bouquet:ScaleTo(bouquet:GetScale()*0.7)
-- faces
local N=128 local IMG={}
for name,data in FACES do
  local buf=buffer.create(N*N*4) local o=0
  for item in string.gmatch(data,"[^,]+") do
    local ci,cnt=string.match(item,"(%d+):(%d+)") local c=PAL[tonumber(ci)+1]
    for _=1,tonumber(cnt) do buffer.writeu8(buf,o,c[1]) buffer.writeu8(buf,o+1,c[2]) buffer.writeu8(buf,o+2,c[3]) buffer.writeu8(buf,o+3,c[4]) o+=4 end
  end
  local ok,img=pcall(function() return AS:CreateEditableImage({Size=Vector2.new(N,N)}) end)
  if ok and img then img:WritePixelsBuffer(Vector2.zero,Vector2.new(N,N),buf) IMG[name]=Content.fromObject(img) else warn("EditableImage fail",img) end
end
-- rigs
local SKIN=Color3.fromRGB(234,184,146)
local folder=Instance.new("Folder") folder.Name="LocalCast" folder.Parent=workspace
local function P(name,size,col,parent) local p=Instance.new("Part") p.Name=name p.Size=size p.Color=col p.Anchored=true p.CanCollide=false p.CastShadow=true p.TopSurface=0 p.BottomSurface=0 p.Material=Enum.Material.SmoothPlastic p.Parent=parent return p end
local function rig(name,torsoCol,legCol)
  local m=Instance.new("Model") m.Name=name m.Parent=folder
  local r={model=m}
  r.T=P("Torso",Vector3.new(2,2,1),torsoCol,m)
  r.H=P("Head",Vector3.new(2,1,1),SKIN,m) local mesh=Instance.new("SpecialMesh") mesh.MeshType=Enum.MeshType.Head mesh.Scale=Vector3.new(1.25,1.25,1.25) mesh.Parent=r.H
  r.face=Instance.new("Decal") r.face.Face=Enum.NormalId.Front r.face.Parent=r.H
  r.LA=P("LArm",Vector3.new(1,2,1),SKIN,m) r.RA=P("RArm",Vector3.new(1,2,1),SKIN,m)
  r.LL=P("LLeg",Vector3.new(1,2,1),legCol,m) r.RL=P("RLeg",Vector3.new(1,2,1),legCol,m)
  r.extra={}
  return r
end
local function A(x,y,z) return CFrame.Angles(math.rad(x or 0),math.rad(y or 0),math.rad(z or 0)) end
-- pose: root = torso CFrame; q = {la={x,y,z},ra=..,ll=..,rl=..,neck=..}
local function pose(r,root,q)
  q=q or {}
  local function g(k) local v=q[k] or {0,0,0} return A(v[1],v[2],v[3]) end
  r.T.CFrame=root
  r.H.CFrame=root*CFrame.new(0,1,0)*g("neck")*CFrame.new(0,0.5,0)
  r.LA.CFrame=root*CFrame.new(-1.5,0.5,0)*g("la")*CFrame.new(0,-0.5,0)
  r.RA.CFrame=root*CFrame.new(1.5,0.5,0)*g("ra")*CFrame.new(0,-0.5,0)
  r.LL.CFrame=root*CFrame.new(-0.5,-1,0)*g("ll")*CFrame.new(0,-1,0)
  r.RL.CFrame=root*CFrame.new(0.5,-1,0)*g("rl")*CFrame.new(0,-1,0)
  for _,e in r.extra do e.p.CFrame=r.H.CFrame*e.rel end
end
local guy=rig("Guy",Color3.fromRGB(40,170,75),Color3.fromRGB(40,40,48))
local girl=rig("Girl",Color3.fromRGB(235,125,165),Color3.fromRGB(70,100,165))
-- girl hair from the R15 template
do
  local tg=sc.Cast.Girl local th=tg.Head
  local acc=tg.Humanoid:GetAccessories()[1]
  local BROWN=Color3.fromRGB(95,58,35)
  if acc then local h=acc.Handle:Clone() h.Anchored=true h.CanCollide=false for _,c in h:GetChildren() do if not c:IsA("SpecialMesh") then c:Destroy() end end h.Parent=girl.model
    local rel=th.CFrame:Inverse()*acc.Handle.CFrame
    table.insert(girl.extra,{p=h,rel=CFrame.new(rel.Position*1.05+Vector3.new(0,0.02,0))*(rel-rel.Position)}) end
  local back=P("BackHair",Vector3.new(1.3,1.9,0.35),BROWN,girl.model)
  table.insert(girl.extra,{p=back,rel=CFrame.new(0,-0.45,0.55)})
end
local curF={}
local function face(r,name) if curF[r]==name then return end curF[r]=name if IMG[name] then r.face.TextureContent=IMG[name] end end
-- open coffin built from parts (lid = mesh coffin leaning)
local CX,CZ=-36,3
do
  local cf=Instance.new("Model") cf.Name="OpenCoffin" cf.Parent=workspace
  local WOOD=Color3.fromRGB(70,40,25) local SAT=Color3.fromRGB(245,240,235)
  P("Bottom",Vector3.new(7,0.4,4.8),WOOD,cf).CFrame=CFrame.new(CX,0.3,CZ)
  P("Satin",Vector3.new(6.6,0.2,4.4),SAT,cf).CFrame=CFrame.new(CX,0.6,CZ)
  P("SideA",Vector3.new(7,1.6,0.25),WOOD,cf).CFrame=CFrame.new(CX,1.2,CZ-2.4)
  P("SideB",Vector3.new(7,1.6,0.25),WOOD,cf).CFrame=CFrame.new(CX,1.2,CZ+2.4)
  P("EndA",Vector3.new(0.25,1.6,4.8),WOOD,cf).CFrame=CFrame.new(CX-3.5,1.2,CZ)
  P("EndB",Vector3.new(0.25,1.6,4.8),WOOD,cf).CFrame=CFrame.new(CX+3.5,1.2,CZ)
  P("Pillow",Vector3.new(1,0.4,1.8),SAT,cf).CFrame=CFrame.new(CX-2.7,0.85,CZ)
  for i=-1,1 do local fl=sc.Bouquet:Clone() fl.Parent=cf fl:PivotTo(CFrame.new(CX+4.4,0.8,CZ+i*1.6)*A(0,i*40,20)) end
  local lid=sc.Coffin:Clone() lid.Parent=cf lid:PivotTo(CFrame.new(CX,4.5,-4.2)*A(0,90,0)*A(70,0,0))
end
-- end walls
for _,x in {-45,45} do P("EndWall",Vector3.new(1,18,20),Color3.fromRGB(235,230,215),workspace).CFrame=CFrame.new(x,9,3) end
-- subtitles
local pg=Players.LocalPlayer:WaitForChild("PlayerGui")
local gui=Instance.new("ScreenGui") gui.Name="Subs" gui.IgnoreGuiInset=true gui.ResetOnSpawn=false gui.DisplayOrder=10 gui.Parent=pg
for _,ax in {0,1} do local sb=Instance.new("Frame") sb.Name="SideBar" sb.BackgroundColor3=Color3.new(0,0,0) sb.BorderSizePixel=0 sb.AnchorPoint=Vector2.new(ax,0) sb.Position=UDim2.fromScale(ax,0) sb.Parent=gui local function fit() local v=workspace.CurrentCamera.ViewportSize sb.Size=UDim2.fromOffset(math.max(0,(v.X-v.Y*9/16)/2),v.Y) end fit() workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fit) end
local black=Instance.new("Frame") black.Size=UDim2.fromScale(1,1) black.BackgroundColor3=Color3.new(0,0,0) black.BorderSizePixel=0 black.Parent=gui
local lbl=Instance.new("TextLabel") lbl.BackgroundTransparency=1 lbl.AnchorPoint=Vector2.new(0.5,0.5) lbl.Position=UDim2.fromScale(0.5,0.68) lbl.Size=UDim2.fromScale(0.4,0.11)
lbl.Font=Enum.Font.GothamBlack lbl.TextScaled=true lbl.TextColor3=Color3.new(1,1,1) lbl.Text="" lbl.Parent=gui
local st=Instance.new("UIStroke") st.Thickness=5 st.Color=Color3.new(0,0,0) st.Parent=lbl
local tsc=Instance.new("UITextSizeConstraint") tsc.MaxTextSize=64 tsc.Parent=lbl
local WORDS={{0.15,"I'M"},{0.45,"THE"},{0.7,"SHYEST"},{1.6,"PERSON"},{2.15,"EVER"},{3.0,"WHEN"},{3.25,"I"},{3.45,"SEE"},{3.75,"MY"},{3.95,"CRUSH"},{4.55,"I"},{4.7,"TRIED"},{5.0,"TO"},{5.2,"GIVE"},{5.45,"HER"},{5.7,"FLOWERS"},{6.5,"AND"},{6.75,"TRIPPED"},{8.05,"OH"},{8.35,"MY..."},{9.15,"R.I.P."}}
local function word(t) local w="" for _,x in WORDS do if t>=x[1] then w=x[2] end end return w end
local function lerp(a,b,t) return a+(b-a)*math.clamp(t,0,1) end
local function ease(t) t=math.clamp(t,0,1) return t*t*(3-2*t) end
local function shake(amp,t) return CFrame.Angles(math.rad(amp*math.noise(t*9,1)),math.rad(amp*math.noise(t*9,2)),0) end
local function look(pos,target,roll) return CFrame.lookAt(pos,target)*CFrame.Angles(0,0,math.rad(roll or 0)) end
local FLOOR=0.1
local function standCF(x,z,dir) local p=Vector3.new(x,FLOOR+3,z) return CFrame.lookAt(p,p+dir) end
local PX=Vector3.new(1,0,0) local NX=Vector3.new(-1,0,0)
local HOLD={la={80,0,-25},ra={80,0,25}}
local function bouquetFront(r) bouquet:PivotTo(r.T.CFrame*CFrame.new(0,-0.5,-1.6)*A(-70,0,0)) end

local function talking(T) -- mouth open flag during subtitle words
  for k,x in WORDS do local nx=WORDS[k+1] local e=nx and nx[1] or x[1]+0.5 if T>=x[1] and T<math.min(e,x[1]+0.5) then return math.floor((T-x[1])/0.11)%2==0 end end
  return false
end
local function blinking(T,off) local p=(T+off)%2.3 return p<0.12 end
local function noise(t,s) return math.noise(t,s or 0,0.5) end

-- background students (walkers + chatting pairs)
local NPCS={}
local npcDefs={
 {kind="walk",x0=-30,x1=20,z=-1.2,speed=3.2,phase=0,shirt=Color3.fromRGB(240,200,60),legs=Color3.fromRGB(40,40,90),face="guy_shy"},
 {kind="walk",x0=25,x1=-25,z=-3.2,speed=2.6,phase=4,shirt=Color3.fromRGB(80,160,230),legs=Color3.fromRGB(60,60,60),face="girl_neutral"},
 {kind="walk",x0=-40,x1=10,z=7.5,speed=2.9,phase=9,shirt=Color3.fromRGB(200,80,200),legs=Color3.fromRGB(30,30,35),face="guy_talk"},
 {kind="chat",x=13,z=9.8,face2=-1,shirt=Color3.fromRGB(250,130,60),legs=Color3.fromRGB(70,90,160),face="girl_talk"},
 {kind="chat",x=10.6,z=9.8,face2=1,shirt=Color3.fromRGB(110,200,140),legs=Color3.fromRGB(40,40,45),face="guy_talk"},
 {kind="chat",x=-14,z=-2.6,face2=1,shirt=Color3.fromRGB(230,90,90),legs=Color3.fromRGB(50,50,60),face="girl_neutral"},
 {kind="chat",x=-11.6,z=-2.6,face2=-1,shirt=Color3.fromRGB(90,90,220),legs=Color3.fromRGB(30,30,30),face="guy_shy"},
}
for i,d in npcDefs do local r=rig("NPC"..i,d.shirt,d.legs) d.r=r face(r,d.face) table.insert(NPCS,d) end
local function updateNPCs(T)
  for i,d in NPCS do
    local r=d.r
    if d.kind=="walk" then
      local len=math.abs(d.x1-d.x0) local dir=(d.x1>d.x0) and 1 or -1
      local x=d.x0+dir*(((T+d.phase)*d.speed)%len)
      local ph=(T+d.phase)*9 local s=math.sin(ph)*35
      local root=standCF(x,d.z,Vector3.new(dir,0,0))+Vector3.new(0,math.abs(math.sin(ph))*0.15,0)
      pose(r,root,{la={-s*0.8,0,-4},ra={s*0.8,0,4},ll={s,0,0},rl={-s,0,0},neck={0,math.sin(T*1.7+i)*15,0}})
    else
      local g=math.sin(T*3+i*2)
      local root=standCF(d.x,d.z,Vector3.new(d.face2,0,0))*A(0,g*6,0)
      pose(r,root,{la={0,0,-4},ra={40+g*40,0,15},neck={g*6,0,g*8}})
      face(r, ((T+i)%2.4<0.12) and (d.face:find("girl") and "girl_blink" or "guy_blink") or (math.floor((T+i)*7)%3==0 and d.face or (d.face:find("girl") and "girl_talk" or "guy_talk")))
    end
  end
end
local LOOP=12.6
local t0=os.clock()+2
RS:BindToRenderStep("Cine",Enum.RenderPriority.Camera.Value+1,function()
  cam.CameraType=Enum.CameraType.Scriptable
  local T=os.clock()-t0
  if T<0 then black.Visible=true lbl.Text="" return end
  T=T%LOOP local fz=workspace:GetAttribute("CineFreeze") if fz then T=fz end
  if T>10.6 then black.Visible=true lbl.Text="" return end
  black.Visible=false lbl.Text=word(T)
  updateNPCs(T)
  -- word pop (scale bounce)
  local wstart=0 for _,x in WORDS do if T>=x[1] then wstart=x[1] end end
  local pop=1+0.25*math.max(0,1-(T-wstart)/0.12) lbl.Size=UDim2.fromScale(0.4*pop,0.11*pop)
  cam.FieldOfView=60
  local talk=talking(T)
  -- girl idle: breathing, sway, head look, blinks
  local gb=math.sin(T*2.2)
  local girlRoot=standCF(4,1,NX)*A(0,gb*4,0)+Vector3.new(0,math.abs(gb)*0.05,0)
  local gq={la={0,0,-4+gb*3},ra={0,0,4-gb*3},neck={0,math.sin(T*1.3)*12,gb*5}}
  local gFace=blinking(T,0.7) and "girl_blink" or "girl_neutral"
  if T<1.5 then
    -- S1 hook: trembling close-up
    local tr=noise(T*25,1)*4
    local root=standCF(-4,1,PX)*A(0,0,tr)
    pose(guy,root,{la={80+noise(T*30,2)*10,0,-25},ra={80+noise(T*30,3)*10,0,25},neck={noise(T*20,4)*8,noise(T*18,5)*10,noise(T*22,6)*6}})
    bouquetFront(guy)
    face(guy, blinking(T,1.0) and "guy_blink" or (talk and "guy_scared_talk" or "guy_scared"))
    local hp=guy.H.Position
    cam.FieldOfView=50
    cam.CFrame=look(hp+Vector3.new(3.6-T*0.5,0.4,1.2),hp+Vector3.new(0,-0.15,0),-24+T*6)*shake(4*(1.5-T)+0.6,T)
  elseif T<3.0 then
    -- S2 shy sway, foot kick, head tilt
    local u=(T-1.5)/1.5
    local sw=math.sin(T*4.5)
    local root=standCF(-4,1,PX)*A(0,sw*12,sw*4)
    pose(guy,root,{la={70+sw*8,0,-25},ra={70-sw*8,0,25},neck={-12,sw*-10,10+sw*8},rl={math.max(0,math.sin(T*6))*35,0,0}})
    bouquetFront(guy)
    face(guy, blinking(T,0.2) and "guy_blink" or (talk and "guy_talk" or "guy_shy"))
    local hp=guy.H.Position
    cam.CFrame=look(hp+Vector3.new(lerp(8,5.5,ease(u)),-0.4,lerp(2.2,1,u)),hp+Vector3.new(0,-1.4,0),4)
  elseif T<4.5 then
    -- S3 crush: hair flip + turns + smile, guy peeks
    local u=(T-3)/1.5
    local flip=math.clamp((T-3.25)/0.5,0,1) local fl=math.sin(flip*math.pi)
    gq={la={0,0,-4},ra={fl*155,0,25*fl},neck={-8*fl,lerp(25,-15,ease(u)),18*fl}}
    girlRoot=standCF(4,1,NX)*A(0,lerp(15,0,ease(u)),0)
    if T>3.9 then gFace=blinking(T,0) and "girl_blink" or "girl_talk" end
    local peek=math.sin(T*3)*0.3
    pose(guy,standCF(-4,1,PX)*A(0,0,6+peek*10),{la=HOLD.la,ra=HOLD.ra,neck={0,0,15}}) bouquetFront(guy)
    face(guy, talk and "guy_talk" or "guy_shy")
    cam.FieldOfView=lerp(55,40,ease(u))
    cam.CFrame=look(guy.H.Position+Vector3.new(-1.6,0.9,1.8),girl.H.Position+Vector3.new(0,-0.7,0),0)
  elseif T<6.5 then
    -- S4 nervous walk with big bounce; girl waves
    local u=(T-4.5)/2
    local x=lerp(-4,0,u)
    local ph=T*11 local s=math.sin(ph)*38
    local root=standCF(x,1,PX)*A(-8,math.sin(ph)*6,math.sin(ph)*4)+Vector3.new(0,math.abs(math.sin(ph))*0.3,0)
    pose(guy,root,{la={80+math.sin(ph)*12,0,-25},ra={80-math.sin(ph)*12,0,25},ll={s,0,0},rl={-s,0,0},neck={math.sin(ph*2)*6,math.sin(T*3)*10,0}})
    bouquetFront(guy)
    face(guy, blinking(T,0.5) and "guy_blink" or (talk and "guy_scared_talk" or "guy_nervous"))
    if T>5.4 then gq={la={0,0,-4},ra={150,0,30+math.sin(T*12)*25},neck={0,0,math.sin(T*4)*10}} gFace="girl_talk" end
    cam.CFrame=look(Vector3.new(x-4.5,4.4,10.2),Vector3.new(x+2.5,2.6,1),0)*shake(0.6,T)
  elseif T<8.0 then
    -- S5 stumble, windmill arms, fall, bounce
    local u=T-6.5
    local feet=CFrame.lookAt(Vector3.new(0,FLOOR,1),Vector3.new(1,FLOOR,1))
    local stumble=math.sin(math.clamp(u/0.15,0,1)*math.pi)*12
    local fall=ease((u-0.1)/0.4)
    local bounce=(u>0.5 and u<0.8) and math.sin((u-0.5)/0.3*math.pi)*0.6 or 0
    local root=feet*A(stumble-87*fall,0,0)*CFrame.new(0,3,0)+Vector3.new(0,0.5*fall+bounce,0)
    local wm=u<0.55 and u*1400 or 0
    local flail=u<0.9 and math.sin(T*30)*20 or 0
    pose(guy,root,{la={lerp(80,170,fall)+math.sin(math.rad(wm))*60,0,-15-flail},ra={lerp(80,170,fall)+math.cos(math.rad(wm))*60,0,15+flail},rl={-25*fall+flail,0,0},ll={10*fall-flail,0,0},neck={-25*fall,0,flail*0.5}})
    face(guy, u<0.55 and "guy_panic" or "guy_shock")
    local k=math.clamp(u/0.7,0,1)
    bouquet:PivotTo(CFrame.new(lerp(1.5,6.8,ease(k)),lerp(3,0.7,k)+math.sin(k*math.pi)*2.5,1.4)*A(u*500,u*200,0))
    local step=ease((u-0.4)/0.3)
    girlRoot=standCF(4+step*0.8,1,NX)*A(-6*step,0,0)
    gq={la={140*step,0,-25*step},ra={140*step,0,25*step},neck={10*step,0,0}}
    gFace=u>0.4 and "girl_gasp" or gFace
    local imp=(u>0.42 and u<0.9) and (0.9-u)*14 or 0
    cam.FieldOfView=55
    cam.FieldOfView=68 cam.CFrame=look(Vector3.new(-0.5,4.8,10.3),Vector3.new(2.6,1.0,1),-8)*shake(imp,T)
  elseif T<9.0 then
    -- S6 crush shocked: hands to mouth, step back, head shake
    local u=T-8
    local feet=CFrame.lookAt(Vector3.new(0,FLOOR,1),Vector3.new(1,FLOOR,1))
    local tw=math.sin(T*25)*6
    pose(guy,feet*A(-87,0,0)*CFrame.new(0,3,0)+Vector3.new(0,0.5,0),{la={170,0,-15+tw},ra={170,0,15-tw},rl={tw,0,0},neck={-25,0,0}})
    bouquet:PivotTo(CFrame.new(6.8,0.7,1.4)*A(0,40,80))
    girlRoot=standCF(4.8+u*0.4,1,NX)*A(-6,0,0)
    gq={la={150,0,-32},ra={150,0,32},neck={8,math.sin(T*14)*14,0}}
    gFace=talk and "girl_gasp" or "girl_shock"
    face(guy,"guy_shock")
    local hp=girl.H.Position
    cam.FieldOfView=lerp(50,32,ease(u/0.25))
    cam.CFrame=look(hp+Vector3.new(-6,0.2,0.8),hp+Vector3.new(0,-0.25,0),0)*shake(1.5,T)
  else
    -- S7 coffin
    local u=(T-9)/1.6
    local pos=Vector3.new(CX+0.3,1.25,CZ)
    local root=CFrame.lookAt(pos,pos+Vector3.yAxis,-PX)
    local tw=(u>0.55 and u<0.75) and math.sin(T*40)*8 or 0
    pose(guy,root,{la={25,0,-8},ra={25+tw,0,8},neck={0,0,tw*0.5}}) face(guy,"guy_dead")
    bouquet:PivotTo(root*CFrame.new(0,-1.6,-0.9)*A(-90,0,0))
    cam.FieldOfView=55
    cam.CFrame=CFrame.lookAt(Vector3.new(CX+0.3,lerp(16,10.5,ease(u)),CZ),Vector3.new(CX+0.3,1,CZ),-PX)*CFrame.Angles(0,0,math.rad(math.sin(T*1.5)*3))
  end
  pose(girl,girlRoot,gq) face(girl,gFace)
end)
